import json, struct, sys

def varint(b, i):
    v = 0
    for k in range(9):
        c = b[i + k]
        if k == 8:
            return (v << 8) | c, i + 9
        v = (v << 7) | (c & 0x7F)
        if c < 0x80:
            return v, i + k + 1

def value(b, i, t):
    sizes = {0: 0, 1: 1, 2: 2, 3: 3, 4: 4, 5: 6, 6: 8, 7: 8, 8: 0, 9: 0}
    if t in (8, 9):
        return t - 8, i
    if t == 7:
        return struct.unpack('>d', b[i:i + 8])[0], i + 8
    if t in sizes:
        n = sizes[t]
        return (int.from_bytes(b[i:i + n], 'big', signed=True) if n else None), i + n
    n = (t - 12) // 2 if t % 2 == 0 else (t - 13) // 2
    raw = b[i:i + n]
    return (raw if t % 2 == 0 else raw.decode('utf-8', 'replace')), i + n

def leaf_rows(b, off, hdr):
    if b[hdr] != 0x0D:
        return
    ncells = struct.unpack('>H', b[hdr + 3:hdr + 5])[0]
    for c in range(ncells):
        p = struct.unpack('>H', b[hdr + 8 + 2 * c:hdr + 10 + 2 * c])[0] + off
        _, p = varint(b, p)
        rowid, p = varint(b, p)
        hsize, q = varint(b, p)
        end, body, types = p + hsize, p + hsize, []
        while q < end:
            t, q = varint(b, q)
            types.append(t)
        cols = []
        for t in types:
            v, body = value(b, body, t)
            cols.append(v)
        yield rowid, cols

data = open(sys.argv[1], 'rb').read()
PAGE = 4096
rows = {}
for off in range(0, len(data) - 7, PAGE):
    hdr = off + 100 if off == 0 and data[:16] == b'SQLite format 3\0' else off
    try:
        for rowid, cols in leaf_rows(data, off, hdr):
            words = [c for c in cols if isinstance(c, str)]
            nums = [c for c in cols if isinstance(c, (int, float)) and not isinstance(c, bool)]
            if words:
                rows[rowid] = {"word": words[0], "value": nums[-1] if nums else None}
    except (IndexError, struct.error):
        pass
out = [rows[k] for k in sorted(rows)]
json.dump(out, open(sys.argv[2], 'w'))
print(len(out), json.dumps(out))
EOF
